// The page the owner has open, read where it is: no navigation, no scrolling, no request.
const norm = (raw) => { const u = new URL(raw); u.hash = ''; let t = u.toString(); if (u.pathname !== '/' && !u.search && t.endsWith('/')) t = t.slice(0, -1); return t; };
const meta = (...names) => { for (const n of names) { const el = document.querySelector(`meta[property="${n}"], meta[name="${n}"]`); const v = el && String(el.getAttribute('content') || '').trim(); if (v) return v; } return null; };
const iso = (s) => { const d = s ? new Date(s) : null; return d && !isNaN(d) ? d.toISOString().replace('.000Z', 'Z') : null; };
const ld = []; for (const s of document.querySelectorAll('script[type="application/ld+json"]')) { try { const v = JSON.parse(s.textContent || 'null'); const stack = [v]; while (stack.length) { const x = stack.pop(); if (!x || typeof x !== 'object') continue; if (Array.isArray(x)) { stack.push(...x); continue; } ld.push(x); if (x['@graph']) stack.push(x['@graph']); } } catch (e) {} }
const ldGet = (k) => { for (const x of ld) if (x[k]) return x[k]; return null; };
const ldName = (v) => { const one = Array.isArray(v) ? v[0] : v; return typeof one === 'string' ? one : (one && one.name) || null; };
const url = norm(location.href);
const key = 'web:page:' + url;
const host = location.hostname.replace(/^www\./, '');
const site = { name: meta('og:site_name') || ldName(ldGet('publisher')) || host, id: host, url: location.origin };
const authorName = meta('author', 'article:author') || ldName(ldGet('author'));
const author = authorName && !/^https?:/.test(authorName) ? { name: authorName } : site;
const timeEl = document.querySelector('time[datetime]');
const published = iso(meta('article:published_time', 'og:published_time', 'date', 'dc.date')) || iso(ldGet('datePublished')) || iso(timeEl && timeEl.getAttribute('datetime')) || new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
const title = meta('og:title') || String(document.title || '').trim() || String((document.querySelector('h1') || {}).textContent || '').trim();
const root = document.querySelector('article') || document.querySelector('main') || document.querySelector('[role="main"]') || document.body;
const SKIP = 'nav, header, footer, aside, form, [role="navigation"], [role="banner"], [role="contentinfo"], [aria-hidden="true"], script, style, noscript';
const BLOCKS = 'h1, h2, h3, h4, p, li, blockquote, pre';
const kindOf = (el) => { const t = el.tagName.toLowerCase(); if (/^h[1-4]$/.test(t)) return 'heading'; if (t === 'li') return 'list_item'; if (t === 'pre') return 'code'; if (t === 'blockquote' || el.closest('blockquote')) return 'quote'; return 'paragraph'; };
const blocks = []; const heads = []; let all = '';
for (const el of root.querySelectorAll(BLOCKS)) {
  if (el.closest(SKIP) && !root.matches(SKIP)) continue;
  if (el.tagName !== 'PRE' && el.querySelector(BLOCKS)) continue;
  const text = String(el.innerText || el.textContent || '').replace(/\s+/g, ' ').trim();
  if (text.length < 2) continue;
  const kind = kindOf(el);
  if (kind === 'heading') { const level = Number(el.tagName[1]); heads.length = Math.max(0, level - 1); heads[level - 1] = text; }
  const path = kind === 'heading' ? heads.slice(0, -1).filter(Boolean) : heads.filter(Boolean);
  const block = { id: 'b' + blocks.length, kind, text };
  if (path.length) block.path = path;
  blocks.push(block); all += text + '\n';
  if (blocks.length >= 2000) break;
}
if (!blocks.length) throw new Error('no readable text on ' + url);
let h = 0x811c9dc5; for (let i = 0; i < all.length; i++) { h ^= all.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
const robots = String(meta('robots') || '').toLowerCase();
const declaredPublic = !!(document.querySelector('link[rel="canonical"]') || meta('og:url')) && !robots.includes('noindex');
const fields = {}; const description = meta('description', 'og:description'); if (description) fields.description = description;
const keywords = meta('keywords'); if (keywords) fields.keywords = keywords.split(',').map((k) => k.trim()).filter(Boolean);
const item = { type: 'rzn.item/v2', key, kind: 'page', url, author, published_at: published, published_in: site,
  marker: 'text:' + h.toString(16) + ':' + all.length, audience: declaredPublic ? 'public' : 'restricted', blocks };
if (title) item.title = title;
if (Object.keys(fields).length) item.fields = fields;
return item;
